using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(entity =>
        {
            entity.HasIndex(s => s.TrackingNumber).IsUnique();

            entity.HasData(
                new Shipment
                {
                    Id = 1,
                    TrackingNumber = "SHP-20260701-1001",
                    Origin = "New York, NY",
                    Destination = "Los Angeles, CA",
                    Status = 2, // InTransit
                    ShippedDate = new DateTime(2026, 7, 1, 0, 0, 0, DateTimeKind.Utc),
                    EstimatedDelivery = new DateTime(2026, 7, 10, 0, 0, 0, DateTimeKind.Utc),
                    RecipientName = "Alice Johnson",
                    Description = "Electronics - 2 boxes"
                },
                new Shipment
                {
                    Id = 2,
                    TrackingNumber = "SHP-20260702-1042",
                    Origin = "Chicago, IL",
                    Destination = "Miami, FL",
                    Status = 3, // OutForDelivery
                    ShippedDate = new DateTime(2026, 7, 2, 0, 0, 0, DateTimeKind.Utc),
                    EstimatedDelivery = new DateTime(2026, 7, 8, 0, 0, 0, DateTimeKind.Utc),
                    RecipientName = "Bob Martinez",
                    Description = "Furniture - 1 pallet"
                },
                new Shipment
                {
                    Id = 3,
                    TrackingNumber = "SHP-20260628-0987",
                    Origin = "Seattle, WA",
                    Destination = "Denver, CO",
                    Status = 4, // Delivered
                    ShippedDate = new DateTime(2026, 6, 28, 0, 0, 0, DateTimeKind.Utc),
                    EstimatedDelivery = new DateTime(2026, 7, 5, 0, 0, 0, DateTimeKind.Utc),
                    ActualDelivery = new DateTime(2026, 7, 4, 0, 0, 0, DateTimeKind.Utc),
                    RecipientName = "Carol White",
