@code {
    private List<ShipmentDto>? shipments;
    private bool isLoading = true;
    private bool showNewForm;
    private bool isCreating;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private string statusMessage = string.Empty;
    private bool statusSuccess;

    private ShipmentDto newShipment = new()
    {
        EstimatedDelivery = DateTime.UtcNow.AddDays(7)
    };

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(filterText))
            {
                var filter = filterText.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(filter, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var parsedStatus))
            {
                result = result.Where(s => s.Status == parsedStatus);
            }

            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleNewShipmentForm()
    {
        showNewForm = !showNewForm;
        if (showNewForm)
        {
            newShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        }
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) ||
            string.IsNullOrWhiteSpace(newShipment.Destination) ||
            string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            ShowStatus("Please fill in all required fields.", false);
            return;
        }

        isCreating = true;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            if (created is not null)
            {
                ShowStatus($"Shipment {created.TrackingNumber} created successfully!", true);
                showNewForm = false;
                await LoadShipments();
            }
            else
            {
                ShowStatus("Failed to create shipment.", false);
            }
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var success = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (success)
            {
                shipment.Status = newStatus;
                ShowStatus($"Shipment {shipment.TrackingNumber} updated to {newStatus}.", true);
            }
            else
            {
                ShowStatus($"Failed to update shipment {shipment.TrackingNumber}.", false);
            }
        }
    }

    private void ShowStatus(string message, bool success)
    {
        statusMessage = message;
        statusSuccess = success;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
